import { PlaneGeometry, Group, Mesh, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // --- Plane background ---
  // Use source rect aspect (512x320 ≈ 1.6) to size the plane.
  const width = 3.0;
  const height = width / (512 / 320); // ≈ 1.875
  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: false,
    depthWrite: true,
  });
  const mesh = new Mesh(geometry, material);
  mesh.position.z = -0.01; // behind text
  group.add(mesh);

  // Load texture asynchronously
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    material.map = tex;
    material.needsUpdate = true;
  });

  // --- Text overlay ---
  const textContent = 'Atelier Noir — precise · luxury · technical';
  const textObj = ctx.fontAtlas.createText(textContent, {
    fontSize: 42,
    color: '#e8ecf2',    // paper
    align: 'center',
    maxWidthPx: 600
  });
  // Center text vertically on the plane
  textObj.position.set(0, -0.02, 0.01);
  group.add(textObj);

  // --- Cleanup ---
  group.userData.cleanup = () => {
    // Kill any gsap timelines (none in this node, but good practice)
    gsap.killTweensOf(group);
    gsap.killTweensOf(textObj);

    // Dispose plane
    geometry.dispose();
    if (material.map) material.map.dispose();
    material.dispose();

    // Remove and dispose text children (font atlas creates meshes)
    textObj.children.forEach((child) => {
      if (child.isMesh) {
        child.geometry.dispose();
        if (child.material) child.material.dispose();
      }
    });
    group.remove(textObj);
    group.remove(mesh);
  };

  // Event handlers (none)
  group.userData.handlers = {};

  return group;
}
